1	package cli
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"net"
9		"net/url"
10		"regexp"
11		"strings"
12		"time"
13	
14		"github.com/spf13/cobra"
15	
16		"github.com/entireio/cli/cmd/entire/cli/auth"
17		"github.com/entireio/cli/internal/coreapi"
18	)
19	
20	// mirrorColumns is the human table/field view of a mirror: the scannable
21	// repo name, the clone URL you'd copy, and whether the upstream is
22	// private. The cluster is omitted — it's already embedded in the clone
23	// URL — and the wire model's internal ids are dropped entirely. The clone
24	// URL is synthesised from the mirror's coords (the form `git clone`
25	// accepts), since the list API doesn't return it.
26	var mirrorColumns = []string{"REPO", "CLONE URL", "PRIVATE"}
27	
28	func mirrorRow(m coreapi.Mirror) []string {
29		repo := m.Owner + "/" + m.Repo
30		cloneURL := fmt.Sprintf("entire://%s/gh/%s/%s", m.ClusterHost, m.Owner, m.Repo)
31		private := "no"
32		if m.IsPrivate.Or(false) {
33			private = "yes"
34		}
35		return []string{repo, cloneURL, private}
36	}
37	
38	// availableMirrorColumns is the view of a repo you *could* mirror: the
39	// scannable repo name, your effective GitHub access, and whether it's
40	// onboardable. STATUS is "available" (run `mirror create` to onboard),
41	// "mirrored" (already done — `mirror list` shows the clone URL), or
42	// "owner-only" (a personal repo of another user; only its owner may mirror
43	// it). No clone URL column: an un-onboarded repo doesn't have one yet.
44	var availableMirrorColumns = []string{"REPO", "ACCESS", "STATUS"}
45	
46	func availableMirrorRow(m coreapi.AvailableMirror) []string {
47		return []string{m.Owner + "/" + m.Repo, string(m.Access), string(m.Status)}
48	}
49	
50	// defaultClusterHost is the cluster the mirror commands target when the
51	// caller omits the <cluster-host> argument. A pragmatic single-region
52	// default for now — once multi-cluster selection lands this should come
53	// from config/context rather than a constant.
54	const defaultClusterHost = "aws-us-east-2.entire.io"
55	
56	// clusterArg returns the cluster host from the optional second positional
57	// (after <github-url>), or defaultClusterHost when it was omitted.
58	func clusterArg(args []string) string {
59		return clusterArgAt(args, 1)
60	}
61	
62	// clusterArgAt returns the cluster host from the optional positional at idx,
63	// or defaultClusterHost when it was omitted. Commands with an intervening
64	// positional (e.g. collaborators add <github-url> <handle> [cluster-host])
65	// pass the trailing index.
66	func clusterArgAt(args []string, idx int) string {
67		if len(args) > idx {
68			return args[idx]
69		}
70		return defaultClusterHost
71	}
72	
73	// clusterHostLabelRe matches one DNS label: alphanumeric, internal hyphens
74	// allowed, no leading/trailing hyphen.
75	var clusterHostLabelRe = regexp.MustCompile(`^[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?$`)
76	
77	// validateClusterHost rejects a cluster host that is anything other than a
78	// bare DNS name or IP with an optional :port. The host is concatenated as
79	// "https://"+host both into the smart-HTTP probe URL (waitForMirrorClone) and
80	// into the STS audience (auth.RepoScopedToken), so a value carrying URL
81	// metacharacters can redirect the request — and the repo-scoped basic-auth
82	// token it carries — somewhere other than the intended cluster. Classic case:
83	// `aws-us-east-2.entire.io@evil.com`, which Go's URL parser reads as
84	// host=evil.com with the real cluster demoted to userinfo, leaking the token
85	// to evil.com. We parse the host the same way the rest of the code does and
86	// require it to round-trip to a bare host with no userinfo, path, query, or
87	// fragment, then confirm the hostname is a valid IP or DNS name. This is
88	// cheap client-side defense-in-depth and doesn't depend on the server's STS
89	// invalid_target canonicalization catching the trick.
90	func validateClusterHost(host string) error {
91		if strings.TrimSpace(host) == "" {
92			return errors.New("cluster host is empty")
93		}
94		u, err := url.Parse("https://" + host)
95		if err != nil {
96			return fmt.Errorf("%q is not a valid host", host)
97		}
98		if u.User != nil || u.Path != "" || u.RawQuery != "" || u.Fragment != "" || u.Host != host {
99			return fmt.Errorf("%q must be a bare host[:port] (no scheme, userinfo, path, query, or fragment)", host)
100		}
101		hostname := u.Hostname()
102		if net.ParseIP(hostname) != nil {
103			return nil
104		}
105		for _, label := range strings.Split(hostname, ".") {
106			if !clusterHostLabelRe.MatchString(label) {
107				return fmt.Errorf("%q is not a valid DNS name or IP", host)
108			}
109		}
110		return nil
111	}
112	
113	// newRepoMirrorCmd is the `entire repo mirror` subtree: manage EntireDB
114	// GitHub-mirror placements on a cluster. Mirrors the standalone entiredb
115	// CLI's `entire repo mirror` surface for the server-side half (create /
116	// list / get / remove). The local-clone rewrite (`mirror use`) is not
117	// ported — it's a git-config + git-remote-entire concern outside the
118	// control-plane API.
119	func newRepoMirrorCmd() *cobra.Command {
120		cmd := &cobra.Command{
121			Use:   "mirror",
122			Short: "Manage GitHub-mirror placements on EntireDB clusters",
123		}
124		cmd.AddCommand(newRepoMirrorCreateCmd())
125		cmd.AddCommand(newRepoMirrorListCmd())
126		cmd.AddCommand(newRepoMirrorGetCmd())
127		cmd.AddCommand(newRepoMirrorRemoveCmd())
128		cmd.AddCommand(newRepoMirrorCollaboratorsCmd())
129		return cmd
130	}
131	
132	func newRepoMirrorCreateCmd() *cobra.Command {
133		var (
134			noWait      bool
135			waitTimeout time.Duration
136		)
137		cmd := &cobra.Command{
138			Use:   "create <github-url> [cluster-host]",
139			Short: "Register a GitHub mirror on a cluster",
140			Long: "Registers a mirror placement for a GitHub repo on the target " +
141				"cluster, then waits for the initial GitHub→EntireDB clone to " +
142				"finish so `git clone` works on return. Pass --no-wait to return " +
143				"as soon as the placement is registered. Idempotent on " +
144				"(upstream, cluster). The cluster-host defaults to " +
145				defaultClusterHost + " when omitted.",
146			Example: "  entire repo mirror create github.com/octocat/hello-world\n" +
147				"  entire repo mirror create github.com/octocat/hello-world eu-west-1.entire.io",
148			Args: cobra.RangeArgs(1, 2),
149			RunE: func(cmd *cobra.Command, args []string) error {
150				owner, repo, err := parseGitHubURL(args[0])
151				if err != nil {
152					cmd.SilenceUsage = true
153					return fmt.Errorf("invalid <github-url>: %w", err)
154				}
155				clusterHost := clusterArg(args)
156				if err := validateClusterHost(clusterHost); err != nil {
157					cmd.SilenceUsage = true
158					return fmt.Errorf("invalid [cluster-host]: %w", err)
159				}
160				return runCoreForCluster(cmd, clusterHost, func(ctx context.Context, c *coreapi.Client) error {
161					created, err := c.CreateMirror(ctx, &coreapi.CreateMirrorInputBody{
162						Provider:    coreapi.CreateMirrorInputBodyProviderGithub,
163						Owner:       owner,
164						Repo:        repo,
165						ClusterHost: clusterHost,
166					})
167					if err != nil {
168						return err
169					}
170					out := cmd.OutOrStdout()
171					repoSlug := "/gh/" + owner + "/" + repo
172					return finishMirrorCreate(out, cmd.ErrOrStderr(), created, noWait,
173						func() error {
174							if _, terr := auth.RepoScopedToken(ctx, clusterHost, repoSlug, "pull"); terr != nil {
175								return fmt.Errorf("probe mirror for suspension: %w", terr)
176							}
177							return nil
178						},
179						func() error {
180							return waitForMirrorClone(ctx, out, clusterHost, owner, repo, waitTimeout)
181						},
182					)
183				})
184			},
185		}
186		cmd.Flags().BoolVar(&noWait, "no-wait", false, "return once the placement is registered, without waiting for the initial clone")
187		cmd.Flags().DurationVar(&waitTimeout, "wait-timeout", 30*time.Minute, "how long to wait for the initial clone to finish")
188		return cmd
189	}
190	
191	// finishMirrorCreate prints the post-create status for `repo mirror create`
192	// and, unless noWait, makes sure the mirror is usable before returning.
193	//
194	// Empty upstream and suspended placement interact. An empty upstream has no
195	// clone to wait for, so the HEAD-poll loop is skipped — it could only spin to
196	// the timeout, since an empty repo never advertises a HEAD. But an *existing*
197	// placement can be suspended even when its upstream is empty, and the
198	// repo-scoped token exchange is the only signal that surfaces that; a *fresh*
199	// create can't be suspended (suspension follows upstream access loss), so it
200	// needs neither the probe nor the wait. Non-empty mirrors take the normal
201	// clone-wait path.
202	//
203	// probeSuspended mints a repo-scoped pull token and returns its error for
204	// explainSuspendedMirror to classify; waitClone runs the HEAD-poll loop. Both
205	// are injected so the branching is unit-testable without the auth and
206	// control-plane stack the production caller wires up.
207	func finishMirrorCreate(out, errW io.Writer, created *coreapi.CreatedMirror, noWait bool, probeSuspended, waitClone func() error) error {
208		if created.Created {
209			fmt.Fprintf(out, "Registered mirror %s\n", created.MirrorId)
210		} else {
211			fmt.Fprintf(out, "Mirror already exists (%s)\n", created.MirrorId)
212		}
213		fmt.Fprintf(out, "  %s\n", created.MirrorUrl)
214	
215		if created.Empty {
216			// An existing placement can sit behind a suspension even with an empty
217			// upstream, so probe the token exchange to surface it. A fresh create
218			// can't be suspended, so skip the probe there.
219			if !created.Created {
220				if err := probeSuspended(); err != nil {
221					if handled, serr := explainSuspendedMirror(errW, created.MirrorId, created.Created, err); handled {
222						return serr
223					}
224					// A non-suspension probe error isn't fatal: the placement exists
225					// and the upstream is genuinely empty, so report that rather than
226					// failing the create on a transient token hiccup.
227				}
228			}
229			fmt.Fprintln(out, "Upstream has no commits yet — nothing to clone. The mirror will pick up refs once the upstream is pushed to.")
230			return nil
231		}
232	
233		if noWait {
234			fmt.Fprintf(out, "Initial clone may still be in progress; `git clone %s` will work once it completes.\n", created.MirrorUrl)
235			return nil
236		}
237		if err := waitClone(); err != nil {
238			if handled, serr := explainSuspendedMirror(errW, created.MirrorId, created.Created, err); handled {
239				return serr
240			}
241			return err
242		}
243		fmt.Fprintf(out, "\nClone it:\n  git clone %s\n", created.MirrorUrl)
244		return nil
245	}
246	
247	func newRepoMirrorListCmd() *cobra.Command {
248		var cluster, provider, owner string
249		var showAvailable bool
250		cmd := &cobra.Command{
251			Use:   "list",
252			Short: "List mirrors you can see (or, with --show-available, repos you could mirror)",
253			Args:  cobra.NoArgs,
254			RunE: func(cmd *cobra.Command, _ []string) error {
255				if showAvailable {
256					return runCoreList(cmd, availableMirrorColumns, availableMirrorRow, func(ctx context.Context, c *coreapi.Client) ([]coreapi.AvailableMirror, error) {
257						// Computed live from GitHub using your own login, so name the
258						// core being dialled (same rationale as the existing-mirror
259						// banner). --cluster/--provider don't apply here: the
260						// onboardable set is cluster-agnostic and GitHub-only.
261						if !jsonRequested(cmd) {
262							fmt.Fprintf(cmd.ErrOrStderr(), "Listing repos you could mirror, via %s\n", c.CoreOrigin())
263						}
264						var params coreapi.ListAvailableMirrorsParams
265						if owner != "" {
266							params.Owner = coreapi.NewOptString(owner)
267						}
268						out, err := c.ListAvailableMirrors(ctx, params)
269						if err != nil {
270							return nil, err
271						}
272						return out.Available, nil
273					})
274				}
275				return runCoreList(cmd, mirrorColumns, mirrorRow, func(ctx context.Context, c *coreapi.Client) ([]coreapi.Mirror, error) {
276					// mirror list is identity-scoped: it shows the mirrors visible
277					// from the active login's federation, so naming that login server
278					// makes a surprising empty result legible — e.g. mirrors in a
279					// different deployment than the active context (--cluster is a
280					// filter, not a router). Name the core the client actually dials
281					// (c.CoreOrigin) so the banner can never diverge from where the
282					// request goes — in particular it reflects ENTIRE_TOKEN's aud,
283					// which a separately-resolved ResolveControlPlaneTarget would miss.
284					// On stderr so it never lands in a piped table; skipped for --json
285					// to keep machine output clean.
286					if !jsonRequested(cmd) {
287						fmt.Fprintf(cmd.ErrOrStderr(), "Listing mirrors on %s\n", c.CoreOrigin())
288					}
289					var params coreapi.ListMirrorsParams
290					if cluster != "" {
291						params.Cluster = coreapi.NewOptString(cluster)
292					}
293					if provider != "" {
294						params.Provider = coreapi.NewOptString(provider)
295					}
296					if owner != "" {
297						params.Owner = coreapi.NewOptString(owner)
298					}
299					out, err := c.ListMirrors(ctx, params)
300					if err != nil {
301						return nil, err
302					}
303					return out.Mirrors, nil
304				})
305			},
306		}
307		cmd.Flags().StringVar(&cluster, "cluster", "", "filter by cluster public host")
308		cmd.Flags().StringVar(&provider, "provider", "", "filter by upstream provider (e.g. github)")
309		cmd.Flags().StringVar(&owner, "owner", "", "filter by upstream owner login")
310		cmd.Flags().BoolVar(&showAvailable, "show-available", false, "instead of existing mirrors, list GitHub repos you could onboard as mirrors (ignores --cluster/--provider)")
311		return cmd
312	}
313	
314	func newRepoMirrorGetCmd() *cobra.Command {
315		return &cobra.Command{
316			Use:   "get <mirror-id>",
317			Short: "Show a mirror by ULID",
318			Args:  cobra.ExactArgs(1),
319			RunE: func(cmd *cobra.Command, args []string) error {
320				return runCoreObject(cmd, mirrorColumns, mirrorRow, func(ctx context.Context, c *coreapi.Client) (*coreapi.Mirror, error) {
321					sc, err := c.GetMirror(ctx, coreapi.GetMirrorParams{MirrorId: args[0]})
322					if err != nil {
323						return nil, err
324					}
325					return sc, nil
326				})
327			},
328		}
329	}
330	
331	func newRepoMirrorRemoveCmd() *cobra.Command {
332		return &cobra.Command{
333			Use:   "remove <github-url> [cluster-host]",
334			Short: "Un-register a GitHub mirror from a cluster",
335			Long: "Removes a mirror placement for a GitHub repo from the target " +
336				"cluster. Other clusters' placements of the same upstream are " +
337				"unaffected. The cluster-host defaults to " + defaultClusterHost +
338				" when omitted.",
339			Example: "  entire repo mirror remove github.com/octocat/hello-world",
340			Args:    cobra.RangeArgs(1, 2),
341			RunE: func(cmd *cobra.Command, args []string) error {
342				owner, repo, err := parseGitHubURL(args[0])
343				if err != nil {
344					cmd.SilenceUsage = true
345					return fmt.Errorf("invalid <github-url>: %w", err)
346				}
347				clusterHost := clusterArg(args)
348				if err := validateClusterHost(clusterHost); err != nil {
349					cmd.SilenceUsage = true
350					return fmt.Errorf("invalid [cluster-host]: %w", err)
351				}
352				return runCoreForCluster(cmd, clusterHost, func(ctx context.Context, c *coreapi.Client) error {
353					// Delete by upstream coords in one call. A 404 is a real
354					// error here, not idempotent success: the server only
355					// answers 204 when it actually removed a placement, so a
356					// 404 ("no such mirror / not visible / different cluster")
357					// surfaces verbatim via renderCoreError rather than being
358					// reported as a successful removal.
359					if err := c.DeleteMirror(ctx, coreapi.DeleteMirrorParams{
360						Provider:    coreapi.DeleteMirrorProviderGithub,
361						Owner:       owner,
362						Repo:        repo,
363						ClusterHost: clusterHost,
364					}); err != nil {
365						return err
366					}
367					cmd.Printf("Removed mirror github.com/%s/%s from %s\n", owner, repo, clusterHost)
368					return nil
369				})
370			},
371		}
372	}
