487	// TestMirrorAdvertisesHead_ReusesConnection is the regression test for the
488	// body drain in mirrorAdvertisesHead. The probe runs every 2s for up to 30m,
489	// and probeClient keeps a small idle pool specifically to reuse the TLS
490	// session across ticks — but Go only returns a connection to that pool when
491	// the response body is read to EOF before Close. If the drain is removed (or
492	// re-capped shorter than the body), the body is left partially read and the
493	// transport closes the connection instead, so every probe pays a fresh
494	// handshake.
495	//
496	// We serve a non-200 with a non-empty body: mirrorAdvertisesHead returns at
497	// the status check without reading the body itself, so the deferred drain is
498	// the *only* thing that consumes it. Counting StateNew transitions then
499	// distinguishes "drained → one reused connection" from "not drained → a new
500	// connection per call".
501	func TestMirrorAdvertisesHead_ReusesConnection(t *testing.T) {
502		t.Parallel()
503	
504		// Larger than any plausible "small cap" someone might reintroduce, so a
505		// capped drain would stop before EOF and fail this test too.
506		body := strings.Repeat("x", 64<<10)
507	
508		var newConns atomic.Int64
509		srv := httptest.NewUnstartedServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
510			// 503 = mirror reachable but not ready; the function returns at the
511			// status check below http.StatusOK without touching the body.
512			w.WriteHeader(http.StatusServiceUnavailable)
513			_, _ = w.Write([]byte(body)) //nolint:errcheck // test server write; failure surfaces as a client error
514		}))
515		srv.Config.ConnState = func(_ net.Conn, state http.ConnState) {
516			if state == http.StateNew {
517				newConns.Add(1)
518			}
519		}
520		srv.Start()
521		defer srv.Close()
522	
523		// Isolated client (not the package-global probeClient) so the idle pool
524		// is private to this test and the assertion stays deterministic under
525		// t.Parallel(). Keep-alives and idle pooling are on by default.
526		client := &http.Client{
527			Timeout:   15 * time.Second,
528			Transport: &http.Transport{MaxIdleConns: 2, MaxIdleConnsPerHost: 2, IdleConnTimeout: 90 * time.Second},
529		}
530	
531		const probes = 5
532		for range probes {
533			ready, status := mirrorAdvertisesHead(context.Background(), client, srv.URL, "tok")
534			require.False(t, ready)
535			require.Equal(t, http.StatusServiceUnavailable, status)
536		}
537	
538		require.Equal(t, int64(1), newConns.Load(),
539			"expected the drained body to let all %d probes share one connection; got %d new connections (body not drained to EOF?)",
540			probes, newConns.Load())
541	}
542	
543	// pktLine encodes s as a git pkt-line (4-hex length prefix including the
544	// prefix itself), mirroring what a smart-HTTP server writes.
545	func pktLine(s string) string { return fmt.Sprintf("%04x%s", len(s)+4, s) }
546	
547	// uploadPackAdvertisement returns a minimal but valid git-upload-pack
548	// info/refs body: the "# service" banner, a flush, a HEAD line carrying the
549	// symref capability, a refs/heads/main line, and a trailing flush. It decodes
550	// to an AdvRefs whose HEAD resolves to refs/heads/main.
551	func uploadPackAdvertisement() string {
552		const sha = "d9a69831082341eab799c062e10ad28b3204c08a"
553		return pktLine("# service=git-upload-pack\n") +
554			"0000" +
555			pktLine(sha+" HEAD\x00symref=HEAD:refs/heads/main\n") +
556			pktLine(sha+" refs/heads/main\n") +
557			"0000"
558	}
559	
560	// TestMirrorAdvertisesHead_FollowsNodeRedirect is the regression test for the
561	// infinite cloning-dots bug. The cluster front door 307-redirects info/refs to
562	// the node holding the mirror; git follows that to clone. The probe used to
563	// refuse all redirects (http.ErrUseLastResponse), so it saw the 307 as "not
564	// 200, not ready" and printed cloning-dots forever even after the clone had
565	// landed. With checkProbeRedirect the probe follows same-host redirects and
566	// reaches the advertisement, so it reports ready.
567	func TestMirrorAdvertisesHead_FollowsNodeRedirect(t *testing.T) {
568		t.Parallel()
569	
570		srv := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
571			if r.URL.Path == "/node/info/refs" {
572				w.Header().Set("Content-Type", "application/x-git-upload-pack-advertisement")
573				_, _ = w.Write([]byte(uploadPackAdvertisement())) //nolint:errcheck // test server write
574				return
575			}
576			// Front door: route to the backing node on the same host, the way the
577			// real cluster front door 307s to bishop.<cluster-host>.
578			http.Redirect(w, r, "/node/info/refs", http.StatusTemporaryRedirect)
579		}))
580		defer srv.Close()
581	
582		// srv.Client() trusts the test cert; layer on the production redirect
583		// policy so we exercise the real follow path.
584		client := srv.Client()
585		client.CheckRedirect = checkProbeRedirect
586	
587		ready, status := mirrorAdvertisesHead(context.Background(), client, srv.URL+"/info/refs", "tok")
588		require.True(t, ready, "probe should follow the node redirect and see HEAD")
589		require.Equal(t, http.StatusOK, status)
590	}
591	
592	func TestCheckProbeRedirect(t *testing.T) {
593		t.Parallel()
594	
595		orig := mustReq(t, "https://aws-us-east-2.entire.io/gh/o/r/info/refs")
596		tests := []struct {
597			name    string
598			target  string
599			via     int
600			wantErr bool
601		}{
602			{name: "same host", target: "https://aws-us-east-2.entire.io/node/info/refs", via: 1},
603			{name: "subdomain node", target: "https://bishop.aws-us-east-2.entire.io/gh/o/r/info/refs", via: 1},
604			{name: "cross host leaks token", target: "https://evil.example.com/info/refs", via: 1, wantErr: true},
605			{name: "sibling suffix trick", target: "https://aws-us-east-2.entire.io.evil.com/x", via: 1, wantErr: true},
606			{name: "non-https", target: "http://bishop.aws-us-east-2.entire.io/x", via: 1, wantErr: true},
607			{name: "too many hops", target: "https://bishop.aws-us-east-2.entire.io/x", via: maxProbeRedirects, wantErr: true},
608		}
609		for _, tt := range tests {
610			t.Run(tt.name, func(t *testing.T) {
611				t.Parallel()
612				via := make([]*http.Request, tt.via)
613				via[0] = orig
614				err := checkProbeRedirect(mustReq(t, tt.target), via)
615				if tt.wantErr {
616					require.Error(t, err)
617				} else {
618					require.NoError(t, err)
619				}
620			})
621		}
622	}
623	
624	func mustReq(t *testing.T, rawURL string) *http.Request {
625		t.Helper()
626		u, err := url.Parse(rawURL)
627		require.NoError(t, err)
628		return &http.Request{URL: u}
629	}
630	
631	// TestWaitForMirrorClone_TimeoutBoundsAuthorization pins that --wait-timeout
632	// covers the authorization phase, not just the probe loop: building the
633	// token source spans cluster discovery and a possible login refresh, so a
634	// hung auth path must be cut off by the user's wait budget.
635	//
636	// Not parallel: swaps the package-level newRepoTokenSource seam.
637	func TestWaitForMirrorClone_TimeoutBoundsAuthorization(t *testing.T) {
638		prev := newRepoTokenSource
639		newRepoTokenSource = func(ctx context.Context, _ string) (repoTokenSource, error) {
640			<-ctx.Done() // hang until the wait deadline fires
641			return nil, ctx.Err()
642		}
643		t.Cleanup(func() { newRepoTokenSource = prev })
644	
645		start := time.Now()
646		err := waitForMirrorClone(context.Background(), io.Discard, "cluster.example", "o", "r", 50*time.Millisecond)
647		require.ErrorIs(t, err, context.DeadlineExceeded)
648		require.Less(t, time.Since(start), 10*time.Second, "authorization must be bounded by the wait timeout")
649	}
