50	func TestCleanupCreatedTrailBranch(t *testing.T) {
51		cases := []struct {
52			name             string
53			localCreated     bool
54			remotePushed     bool
55			checkoutBranch   bool
56			wantLocalBranch  bool
57			wantRemoteBranch bool
58		}{
59			{
60				name:             "removes local branch only",
61				localCreated:     true,
62				remotePushed:     false,
63				wantLocalBranch:  false,
64				wantRemoteBranch: false,
65			},
66			{
67				name:             "removes local and pushed remote branch",
68				localCreated:     true,
69				remotePushed:     true,
70				wantLocalBranch:  false,
71				wantRemoteBranch: false,
72			},
73			{
74				name:             "does not delete remote when checked out branch cannot be removed locally",
75				localCreated:     true,
76				remotePushed:     true,
77				checkoutBranch:   true,
78				wantLocalBranch:  true,
79				wantRemoteBranch: true,
80			},
81			{
82				name:             "deletes remote when local was not created by cleanup owner",
83				localCreated:     false,
84				remotePushed:     true,
85				wantLocalBranch:  true,
86				wantRemoteBranch: false,
87			},
88		}
89	
90		for _, tc := range cases {
91			t.Run(tc.name, func(t *testing.T) {
92				branch := "cleanup-test"
93				localDir, originDir, repo := initTrailCleanupRepo(t)
94				defer repo.Close()
95				t.Chdir(localDir)
96	
97				runGitTrailTest(t, localDir, "branch", branch)
98				if tc.remotePushed {
99					runGitTrailTest(t, localDir, "push", "origin", branch)
100				}
101				if tc.checkoutBranch {
102					runGitTrailTest(t, localDir, "checkout", branch)
103				}
104	
105				var errBuf bytes.Buffer
106				cleanupCreatedTrailBranch(repo, branch, tc.localCreated, tc.remotePushed, &errBuf)
107	
108				require.Equal(t, tc.wantLocalBranch, gitBranchExistsTrailTest(t, localDir, branch), "local branch mismatch; stderr: %s", errBuf.String())
109				require.Equal(t, tc.wantRemoteBranch, gitBranchExistsTrailTest(t, originDir, branch), "remote branch mismatch; stderr: %s", errBuf.String())
110				if tc.checkoutBranch {
111					require.Contains(t, errBuf.String(), "not deleting remote branch")
112				}
113			})
114		}
115	}
