18	// CoreOrigin reports the scheme://host the client dials, with the apiBasePath
19	// (and any trailing slash) stripped — the single source of truth display sites
20	// use so the named core can't diverge from where requests go.
21	func TestClient_CoreOrigin(t *testing.T) {
22		t.Parallel()
23		tests := []struct {
24			name    string
25			coreURL string
26			want    string
27		}{
28			{name: "bare origin", coreURL: "https://eu.auth.entire.io", want: "https://eu.auth.entire.io"},
29			{name: "trailing slash", coreURL: "https://eu.auth.entire.io/", want: "https://eu.auth.entire.io"},
30			{name: "with port", coreURL: "https://localhost:8443", want: "https://localhost:8443"},
31		}
32		for _, tt := range tests {
33			t.Run(tt.name, func(t *testing.T) {
34				t.Parallel()
35				c, err := NewWithBearer(tt.coreURL, "tok")
36				if err != nil {
37					t.Fatalf("NewWithBearer: %v", err)
38				}
39				if got := c.CoreOrigin(); got != tt.want {
40					t.Fatalf("CoreOrigin() = %q, want %q (apiBasePath and trailing slash must be stripped)", got, tt.want)
41				}
42			})
43		}
44	}
45	
46	// The whole point of the getter: a client built through the ENTIRE_TOKEN bypass
47	// reports the token's aud, so a display site asking the client "which core?"
48	// names the core the request actually dials — not a stale active context that a
49	// separate ResolveControlPlaneTarget would return.
50	//
51	// Not parallel: sets ENTIRE_TOKEN (process-global).
52	func TestNew_CoreOrigin_HonoursEnvToken(t *testing.T) {
53		const core = "https://core.us.entire.io"
54		t.Setenv(auth.EnvTokenVar, makeAudJWT(core))
55		c, err := New()
56		if err != nil {
57			t.Fatalf("New: %v", err)
58		}
59		if got := c.CoreOrigin(); got != core {
60			t.Fatalf("CoreOrigin() = %q, want the env token's aud %q", got, core)
61		}
62	}
63	
64	// makeAudJWT builds a JWT carrying only an aud claim. CoreURLFromEnvToken reads
65	// aud without verifying the signature, so the "sig" is a placeholder — but the
66	// header must name a real alg (alg:none is refused), matching how login JWTs
67	// look on the wire.
68	func makeAudJWT(aud string) string {
69		enc := base64.RawURLEncoding
70		header := enc.EncodeToString([]byte(`{"alg":"HS256","typ":"JWT"}`))
71		payload := enc.EncodeToString([]byte(`{"aud":"` + aud + `"}`))
72		return header + "." + payload + "." + enc.EncodeToString([]byte("sig"))
73	}
74	
75	func TestAPIError(t *testing.T) {
76		t.Parallel()
77	
78		tests := []struct {
79			name string
80			err  error
81			want string
82		}{
83			{
84				name: "nil error",
85				err:  nil,
86				want: "",
87			},
88			{
89				name: "non-API error returns empty",
90				err:  errors.New("dial tcp: connection refused"),
91				want: "",
92			},
93			{
94				name: "prefers detail",
95				err: &ErrorModelStatusCode{
96					StatusCode: 409,
97					Response: ErrorModel{
98						Title:  NewOptString("Conflict"),
99						Detail: NewOptString("organization name already taken"),
100					},
101				},
102				want: "organization name already taken",
103			},
104			{
105				name: "falls back to title when detail empty",
106				err: &ErrorModelStatusCode{
107					StatusCode: 403,
108					Response:   ErrorModel{Title: NewOptString("Forbidden")},
109				},
110				want: "Forbidden",
111			},
112			{
113				name: "falls back to status when title and detail empty",
114				err:  &ErrorModelStatusCode{StatusCode: 500},
115				want: "control-plane request failed with status 500",
116			},
117			{
118				name: "unwraps a wrapped API error",
119				err: fmt.Errorf("create org: %w", &ErrorModelStatusCode{
120					StatusCode: 422,
121					Response:   ErrorModel{Detail: NewOptString("name is required")},
122				}),
123				want: "name is required",
124			},
125		}
126		for _, tc := range tests {
127			t.Run(tc.name, func(t *testing.T) {
128				t.Parallel()
129				if got := APIError(tc.err); got != tc.want {
130					t.Errorf("APIError() = %q, want %q", got, tc.want)
131				}
132			})
133		}
134	}
135	
136	// TestProviderSource_BearerAuth covers the three branches of the
137	// token-provider SecuritySource New() builds: a token passes through, a
138	// not-logged-in error gets the login hint, and any other error surfaces
139	// under the control-plane-token wrapper rather than the login hint.
140	func TestProviderSource_BearerAuth(t *testing.T) {
141		t.Parallel()
142	
143		t.Run("token passes through", func(t *testing.T) {
144			t.Parallel()
145			src := &providerSource{provide: func(context.Context) (string, error) { return "tok-123", nil }}
146			got, err := src.BearerAuth(context.Background(), "")
147			if err != nil {
148				t.Fatalf("BearerAuth: %v", err)
149			}
150			if got.Token != "tok-123" {
151				t.Fatalf("Token = %q, want tok-123", got.Token)
152			}
153		})
154	
155		t.Run("not-logged-in maps to login hint", func(t *testing.T) {
156			t.Parallel()
157			src := &providerSource{provide: func(context.Context) (string, error) {
158				return "", fmt.Errorf("wrapped: %w", auth.ErrNotLoggedIn)
159			}}
160			_, err := src.BearerAuth(context.Background(), "")
161			if err == nil || !strings.Contains(err.Error(), "entire login") {
162				t.Fatalf("error = %v, want a login hint", err)
163			}
164			if !errors.Is(err, auth.ErrNotLoggedIn) {
165				t.Fatalf("error must wrap ErrNotLoggedIn, got %v", err)
166			}
167		})
168	
169		t.Run("other errors surface verbatim", func(t *testing.T) {
170			t.Parallel()
171			// The active-context provider returns an already-tailored message; it
172			// must reach the user unprefixed (no generic "resolve control-plane
173			// token" wrapper burying it) and without the login hint.
174			sentinel := errors.New("no usable login for \"ctx\" (https://core.example); run `entire login --server https://core.example`")
175			src := &providerSource{provide: func(context.Context) (string, error) { return "", sentinel }}
176			_, err := src.BearerAuth(context.Background(), "")
177			if err == nil || err.Error() != sentinel.Error() {
178				t.Fatalf("error = %v, want the provider message surfaced verbatim", err)
179			}
180		})
181	}
182	
183	// providerSource must skip SessionAuth so no Cookie header is added — same
184	// contract as bearerOnlySource below, asserted here at the unit level.
185	func TestProviderSource_SkipsSessionAuth(t *testing.T) {
186		t.Parallel()
187		src := &providerSource{provide: func(context.Context) (string, error) { return "", nil }}
188		if _, err := src.SessionAuth(context.Background(), ""); !errors.Is(err, ogenerrors.ErrSkipClientSecurity) {
189			t.Fatalf("SessionAuth err = %v, want ErrSkipClientSecurity", err)
190		}
191	}
192	
193	// bearerOnlySource mirrors the CLI's bearerSource contract: a fixed
194	// bearer token, and ErrSkipClientSecurity for sessionAuth so the
195	// generated middleware does NOT add a `Cookie: entire_session=` header.
196	// Used by TestBearerOnlySource_NoCookieOnTheWire to nail down the
197	// "bearer-only, no cookie" contract at the HTTP layer.
198	type bearerOnlySource struct{}
199	
200	func (bearerOnlySource) BearerAuth(context.Context, OperationName) (BearerAuth, error) {
201		return BearerAuth{Token: "test-bearer"}, nil
202	}
203	
204	func (bearerOnlySource) SessionAuth(context.Context, OperationName) (SessionAuth, error) {
205		return SessionAuth{}, ogenerrors.ErrSkipClientSecurity
206	}
207	
208	// TestBearerOnlySource_NoCookieOnTheWire documents the SessionAuth
209	// empty-value contract by checking the wire: any operation issued by a
210	// Client built with a SessionAuth-skipping source must NOT carry a
211	// Cookie header. (ogen's securitySessionAuth unconditionally calls
212	// req.AddCookie, so returning SessionAuth{} with a nil error would send
213	// an empty `entire_session=` cookie; only ErrSkipClientSecurity prevents
214	// the cookie from being added.)
215	func TestBearerOnlySource_NoCookieOnTheWire(t *testing.T) {
216		t.Parallel()
217	
218		// The handler runs on httptest's goroutine and the assertion runs
219		// on the test goroutine; HTTP completion isn't a happens-before
220		// edge the race detector recognises. Pass the captured header
221		// across through a buffered channel so -race stays happy.
222		cookieCh := make(chan string, 1)
223		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
224			cookieCh <- r.Header.Get("Cookie")
225			w.Header().Set("Content-Type", "application/json")
226			// Minimal valid ListOrgMembersOutputBody payload so the response
227			// decoder doesn't blow up; we only care about the inbound headers.
228			w.WriteHeader(http.StatusOK)
229			if _, err := w.Write([]byte(`{"members":[]}`)); err != nil {
230				t.Errorf("writing test response: %v", err)
231			}
232		}))
233		t.Cleanup(srv.Close)
234	
235		c, err := NewClient(srv.URL, bearerOnlySource{})
236		if err != nil {
237			t.Fatalf("NewClient: %v", err)
238		}
239	
240		// ListOrgMembers is a simple GET that exercises the security
241		// middleware; the result itself is irrelevant to this test.
242		if _, err := c.ListOrgMembers(context.Background(), ListOrgMembersParams{OrgId: "01H000000000000000000000A1"}); err != nil {
243			t.Fatalf("ListOrgMembers: %v", err)
244		}
245	
246		cookieHeader := <-cookieCh
247		if cookieHeader != "" {
248			t.Errorf("outbound Cookie header = %q, want empty (bearer-only contract)", cookieHeader)
249		}
